int main() {
    int n;
    scanf("%d", &n);

    double p[n+1]; // probabilities for keys (1-indexed)
    double q[n+2]; // probabilities for dummy keys (0 to n)

    for (int i = 1; i <= n; i++) {
        scanf("%lf", &p[i]);
    }
    for (int i = 0; i <= n; i++) {
        scanf("%lf", &q[i]);
    }

    // e[i][j] = expected cost of optimal BST for keys i..j
    double e[n+2][n+1];
    // w[i][j] = sum of probabilities for keys i..j and dummy keys i-1..j
    double w[n+2][n+1];
    // root[i][j] = root of optimal BST for keys i..j (optional, not needed for result)

    // Initialize for empty subtrees
    for (int i = 1; i <= n+1; i++) {
        e[i][i-1] = q[i-1];
        w[i][i-1] = q[i-1];
    }

    // Compute for increasing lengths
    for (int len = 1; len <= n; len++) {
        for (int i = 1; i <= n - len + 1; i++) {
            int j = i + len - 1;
            e[i][j] = INT_MAX;
            w[i][j] = w[i][j-1] + p[j] + q[j];

            // Try each key as root
            for (int r = i; r <= j; r++) {
                double cost = e[i][r-1] + e[r+1][j] + w[i][j];
                if (cost < e[i][j]) {
                    e[i][j] = cost;
                }
            }
        }
    }

    printf("%.2f\n", e[1][n]);

    return 0;
}

