int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    double *p = (double *)malloc((n + 1) * sizeof(double));   // 1..n
    double *q = (double *)malloc((n + 1) * sizeof(double));   // 0..n

    for (int i = 1; i <= n; i++) scanf("%lf", &p[i]);
    for (int i = 0; i <= n; i++) scanf("%lf", &q[i]);

    int N = n + 2;
    double *e = (double *)calloc((N) * (N), sizeof(double));
    double *w = (double *)calloc((N) * (N), sizeof(double));

    #define E(i,j) e[(i) * N + (j)]
    #define W(i,j) w[(i) * N + (j)]

    for (int i = 1; i <= n + 1; i++) {
        E(i, i - 1) = q[i - 1];
        W(i, i - 1) = q[i - 1];
    }

    for (int l = 1; l <= n; l++) {
        for (int i = 1; i <= n - l + 1; i++) {
            int j = i + l - 1;
            E(i, j) = 1e100;
            W(i, j) = W(i, j - 1) + p[j] + q[j];
            for (int r = i; r <= j; r++) {
                double val = E(i, r - 1) + E(r + 1, j) + W(i, j);
                if (val < E(i, j)) E(i, j) = val;
            }
        }
    }

    printf("%.6f\n", E(1, n));

    free(p);
    free(q);
    free(e);
    free(w);
    return 0;
}

