#include <bits/stdc++.h>
using namespace std;

/*
Optimal Binary Search Tree

Given:
- n keys
- probabilities p1..pn for successful searches of keys
- probabilities q0..qn for unsuccessful searches (dummy keys)

We compute the minimum expected search cost of the optimal BST using
the classic dynamic programming recurrence:

e[i][j] = minimum expected cost for keys ki..kj
w[i][j] = sum of probabilities p_i..p_j and q_{i-1}..q_j

Base:
e[i][i-1] = q[i-1]
w[i][i-1] = q[i-1]

Transition:
e[i][j] = min over r in [i..j] of ( e[i][r-1] + e[r+1][j] + w[i][j] )

Input format assumed:
n
p1 p2 ... pn
q0 q1 ... qn

Output:
minimum expected cost

Printed with fixed precision.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<double> p(n + 1), q(n + 1);
    for (int i = 1; i <= n; ++i) cin >> p[i];
    for (int i = 0; i <= n; ++i) cin >> q[i];

    const double INF = 1e100;

    // Use 1-based indexing as in the standard OBST algorithm.
    vector<vector<double>> e(n + 2, vector<double>(n + 1, 0.0));
    vector<vector<double>> w(n + 2, vector<double>(n + 1, 0.0));

    for (int i = 1; i <= n + 1; ++i) {
        e[i][i - 1] = q[i - 1];
        w[i][i - 1] = q[i - 1];
    }

    for (int len = 1; len <= n; ++len) {
        for (int i = 1; i + len - 1 <= n; ++i) {
            int j = i + len - 1;
            e[i][j] = INF;
            w[i][j] = w[i][j - 1] + p[j] + q[j];
            for (int r = i; r <= j; ++r) {
                double cur = e[i][r - 1] + e[r + 1][j] + w[i][j];
                if (cur < e[i][j]) e[i][j] = cur;
            }
        }
    }

    cout << fixed << setprecision(6) << e[1][n] << '\n';
    return 0;
}

import java.io.*;
