public class OptimalBST {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read number of keys
        int n = Integer.parseInt(br.readLine().trim());

        // Read probabilities for keys (p_i)
        double[] p = new double[n + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            p[i] = Double.parseDouble(st.nextToken());
        }

        // Read probabilities for dummy keys (q_i)
        double[] q = new double[n + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i <= n; i++) {
            q[i] = Double.parseDouble(st.nextToken());
        }

        // e[i][j] = optimal expected cost for subtree with keys i..j
        double[][] e = new double[n + 2][n + 1];
        // w[i][j] = sum of probabilities in subtree i..j
        double[][] w = new double[n + 2][n + 1];

        // Initialize for dummy keys (empty subtrees)
        for (int i = 1; i <= n + 1; i++) {
            e[i][i - 1] = q[i - 1];
            w[i][i - 1] = q[i - 1];
        }

        // Build optimal BST bottom-up
        for (int len = 1; len <= n; len++) {
            for (int i = 1; i <= n - len + 1; i++) {
                int j = i + len - 1;
                e[i][j] = Double.MAX_VALUE;
                w[i][j] = w[i][j - 1] + p[j] + q[j];

                // Try each key as root
                for (int r = i; r <= j; r++) {
                    double cost = e[i][r - 1] + e[r + 1][j] + w[i][j];
                    if (cost < e[i][j]) {
                        e[i][j] = cost;
                    }
                }
            }
        }

        // Output the expected cost with 4 decimal places
        System.out.printf("%.4f\n", e[1][n]);
    }
}

