import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        double[] p = new double[n + 1];     // 1..n
        double[] q = new double[n + 1];     // 0..n

        for (int i = 1; i <= n; i++) p[i] = fs.nextDouble();
        for (int i = 0; i <= n; i++) q[i] = fs.nextDouble();

        // CLRS optimal BST DP
        // e[i][j] = optimal expected cost for keys ki..kj
        // w[i][j] = sum of probabilities pi..pj and qi-1..qj
        // indices: 1 <= i <= n+1, 0 <= j <= n
        double[][] e = new double[n + 2][n + 1];
        double[][] w = new double[n + 2][n + 1];

        for (int i = 1; i <= n + 1; i++) {
            e[i][i - 1] = q[i - 1];
            w[i][i - 1] = q[i - 1];
        }

        for (int l = 1; l <= n; l++) {
            for (int i = 1; i <= n - l + 1; i++) {
                int j = i + l - 1;
                e[i][j] = Double.POSITIVE_INFINITY;
                w[i][j] = w[i][j - 1] + p[j] + q[j];
                for (int r = i; r <= j; r++) {
                    double t = e[i][r - 1] + e[r + 1][j] + w[i][j];
                    if (t < e[i][j]) e[i][j] = t;
                }
            }
        }

        System.out.printf(Locale.US, "%.6f%n", e[1][n]);
    }
}
